ALTER TABLE "inventory_items" ADD CONSTRAINT "inventory_items_non_negative_quantities_check" CHECK ("inventory_items"."total_quantity" >= 0 AND "inventory_items"."reserved_quantity" >= 0 AND "inventory_items"."checked_out_quantity" >= 0 AND "inventory_items"."damaged_quantity" >= 0 AND "inventory_items"."minimum_stock" >= 0);--> statement-breakpoint
ALTER TABLE "inventory_items" ADD CONSTRAINT "inventory_items_stock_conservation_check" CHECK ("inventory_items"."total_quantity" >= ("inventory_items"."reserved_quantity" + "inventory_items"."checked_out_quantity" + "inventory_items"."damaged_quantity"));